package com.mfix.pos;

import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.webkit.WebView;

/** Adds practical period and product sales analytics to the existing reports view. */
public class ReportsAnalyticsPatchActivity extends DailyClosingPatchActivity {
    private static final String PATCH =
        "(function(){if(window.__mfixReportsAnalyticsV3)return;window.__mfixReportsAnalyticsV3=true;"+
        "function read(k,d){try{var v=JSON.parse(localStorage.getItem(k));return v==null?d:v;}catch(e){return d;}}"+
        "function sales(){var a=read('mfix_completed_sales_v1',[]);return Array.isArray(a)?a:[];}"+
        "function returns(){var a=read('mfix_sales_returns_v1',[]);return Array.isArray(a)?a:[];}"+
        "function money(v){return Number(v||0).toLocaleString('he-IL',{minimumFractionDigits:2,maximumFractionDigits:2});}"+
        "function dateOf(x){return new Date(x.at||x.createdAt||x.date||x.timestamp||0);}"+
        "function paymentRows(s){var p=s.payment||s.currentPayment||{};if(Array.isArray(s.payments)&&s.payments.length)return s.payments;if(Array.isArray(s.paymentRows)&&s.paymentRows.length)return s.paymentRows;if(Array.isArray(p.parts)&&p.parts.length)return p.parts;return [{method:p.method||s.paymentMethod||s.paymentType||'other',amount:Number(p.amount||s.paid||s.amountPaid||s.totalIncl||s.total||0)}];}"+
        "function methodKey(m){m=String(m||'other').toLowerCase();if(m==='cash'||m==='מזומן')return 'cash';if(m==='card'||m==='credit'||m==='credit_card'||m==='אשראי')return 'card';if(m==='transfer'||m==='bank_transfer'||m==='העברה')return 'transfer';if(m==='check'||m==='cheque'||m==='צק'||m==='צ׳ק')return 'check';return 'other';}"+
        "function costOf(i){var v=i.costPrice!=null?i.costPrice:i.purchasePrice!=null?i.purchasePrice:i.cost!=null?i.cost:i.buyPrice;v=Number(v);return isFinite(v)&&v>=0?v:null;}"+
        "function render(){var v=document.getElementById('view-reports');if(!v)return false;if(document.getElementById('mfixReportsAnalytics'))return true;var b=document.createElement('div');b.id='mfixReportsAnalytics';b.className='card';b.style.marginTop='12px';b.innerHTML='<div class=\"section-title\">📊 ניתוח מכירות</div><div class=\"muted\">דוח לתקופה נבחרת, מוצרים מובילים ורווח גולמי כאשר עלות המוצר זמינה.</div><div class=\"grid2\" style=\"margin-top:10px\"><div class=\"field\"><label class=\"flabel\">מתאריך</label><input id=\"mfixReportFrom\" class=\"input\" type=\"date\"></div><div class=\"field\"><label class=\"flabel\">עד תאריך</label><input id=\"mfixReportTo\" class=\"input\" type=\"date\"></div></div><button id=\"mfixBuildReport\" class=\"btn btn-primary\" style=\"margin-top:10px\">הצג דוח</button><div id=\"mfixReportBody\" style=\"margin-top:12px\"></div>';var now=new Date(),iso=function(d){return d.toISOString().slice(0,10);};b.querySelector('#mfixReportTo').value=iso(now);var start=new Date(now);start.setDate(start.getDate()-6);b.querySelector('#mfixReportFrom').value=iso(start);function build(){var from=b.querySelector('#mfixReportFrom').value,to=b.querySelector('#mfixReportTo').value,until=new Date(to+'T23:59:59'),ss=sales().filter(function(s){var d=dateOf(s);return d>=new Date(from+'T00:00:00')&&d<=until;}),rr=returns().filter(function(r){var d=dateOf(r);return d>=new Date(from+'T00:00:00')&&d<=until;}),gross=0,refund=0,costTotal=0,items={},pay={cash:0,card:0,transfer:0,check:0,other:0},costKnown=0,costMissing=0;ss.forEach(function(s){gross+=Number(s.totalIncl||s.total||s.amount||0);paymentRows(s).forEach(function(p){var k=methodKey(p.method||p.type);pay[k]+=Number(p.amount||p.value||0);});(s.items||[]).forEach(function(i){var key=String(i.name||i.title||i.productName||i.sku||'מוצר'),q=Number(i.qty||i.quantity||1),revenue=Number(i.price||i.unitPrice||i.salePrice||0)*q,cost=costOf(i);if(!items[key])items[key]={qty:0,revenue:0,cost:0,costKnownQty:0};items[key].qty+=q;items[key].revenue+=revenue;if(cost!==null){items[key].cost+=cost*q;items[key].costKnownQty+=q;costTotal+=cost*q;costKnown+=q;}else{costMissing+=q;}});});rr.forEach(function(r){refund+=Number(r.refundTotal||r.total||r.amount||0);});var top=Object.keys(items).map(function(k){return {name:k,qty:items[k].qty,revenue:items[k].revenue,cost:items[k].cost,profit:items[k].revenue-items[k].cost,costComplete:items[k].costKnownQty===items[k].qty};}).sort(function(a,c){return c.qty-a.qty;}).slice(0,10);var rows=top.map(function(x){return '<tr><td>'+x.name.replace(/[<>]/g,'')+'</td><td>'+x.qty+'</td><td>₪'+money(x.revenue)+'</td><td>'+(x.costComplete?'₪'+money(x.cost):'—')+'</td><td>'+(x.costComplete?'₪'+money(x.profit):'—')+'</td></tr>';}).join('');var net=gross-refund,profit=net-costTotal,margin=net>0?(profit/net*100):0;var costNote=costMissing>0?'<div class=\"muted\" style=\"margin-top:8px\">עלות חסרה עבור '+costMissing+' יחידות; הרווח הכולל מוצג רק על בסיס עלויות שנמצאו בנתוני המכירה.</div>':'<div class=\"muted\" style=\"margin-top:8px\">עלות קיימת לכל יחידות המכירה בתקופה.</div>';b.querySelector('#mfixReportBody').innerHTML='<div class=\"grid4\"><div><b>עסקאות</b><div>'+ss.length+'</div></div><div><b>ברוטו</b><div>₪'+money(gross)+'</div></div><div><b>החזרים</b><div>₪'+money(refund)+'</div></div><div><b>נטו</b><div>₪'+money(net)+'</div></div></div><div class=\"grid4\" style=\"margin-top:10px\"><div><b>עלות ידועה</b><div>₪'+money(costTotal)+'</div></div><div><b>רווח גולמי</b><div>₪'+money(profit)+'</div></div><div><b>מרווח</b><div>'+money(margin)+'%</div></div><div><b>יחידות עם עלות</b><div>'+costKnown+'</div></div></div>'+costNote+'<div style=\"margin-top:10px;display:flex;gap:8px;flex-wrap:wrap\"><span class=\"pill blue\">מזומן: ₪'+money(pay.cash)+'</span><span class=\"pill blue\">אשראי: ₪'+money(pay.card)+'</span><span class=\"pill blue\">העברה: ₪'+money(pay.transfer)+'</span><span class=\"pill blue\">צ׳ק: ₪'+money(pay.check)+'</span><span class=\"pill blue\">אחר: ₪'+money(pay.other)+'</span></div><div style=\"overflow:auto;margin-top:12px\"><table class=\"table\"><thead><tr><th>מוצר</th><th>כמות</th><th>מכירות</th><th>עלות</th><th>רווח</th></tr></thead><tbody>'+rows+'</tbody></table></div>';};b.querySelector('#mfixBuildReport').onclick=build;build();return true;}var n=0,t=setInterval(function(){if(render()||n++>=40)clearInterval(t);},500);})();";

    /** Installs the analytics layer on an already-active reports view. */
    public static void install(WebView webView){
        if(webView!=null) webView.postDelayed(()->webView.evaluateJavascript(PATCH,null),750);
    }

    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        View root=((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);
        if(root instanceof WebView)((WebView)root).postDelayed(()->((WebView)root).evaluateJavascript(PATCH,null),6800);
    }
}
